const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometry around Depok, Indonesia
  const depok = ee.Geometry.Point([106.7942, -6.4025]);
  const region = depok.buffer(5000); // 5km buffer around Depok

  // Define time periods
  const start1990 = '1990-01-01';
  const end1990 = '1990-12-31';
  const start2019 = '2019-01-01';
  const end2019 = '2019-12-31';

  // Function to mask clouds for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const cloudShadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to mask clouds for Landsat 8
  function maskL8Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const cloudShadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    if (image.get('SPACECRAFT_ID').getInfo().includes('LANDSAT_5')) {
      // Landsat 5: B3=Red, B4=NIR
      return image.addBands(image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI'));
    } else {
      // Landsat 8: B4=Red, B5=NIR  
      return image.addBands(image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI'));
    }
  }

  // Get Landsat 5 collection for 1990
  const landsat5_1990 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(start1990, end1990)
    .filterBounds(region)
    .map(maskL5Clouds)
    .map(addNDVI);

  // Get Landsat 8 collection for 2019  
  const landsat8_2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2019, end2019)
    .filterBounds(region)
    .map(maskL8Clouds)
    .map(addNDVI);

  // Check collection sizes
  const count1990 = landsat5_1990.size().getInfo();
  const count2019 = landsat8_2019.size().getInfo();

  console.log(`1990 Images: ${count1990}`);
  console.log(`2019 Images: ${count2019}`);

  if (count1990 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const composite1990 = landsat5_1990.median();
  const composite2019 = landsat8_2019.median();

  // Calculate mean NDVI and pixel counts
  const ndvi1990 = composite1990.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const ndvi2019 = composite2019.reduceRegion({
    reducer: ee.Reducer.mean(), 
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const count1990Pixels = composite1990.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const count2019Pixels = composite2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region, 
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const ndvi1990Val = ndvi1990.getInfo();
  const ndvi2019Val = ndvi2019.getInfo();
  const count1990Val = count1990Pixels.getInfo();
  const count2019Val = count2019Pixels.getInfo();

  console.log(`1990 NDVI: ${ndvi1990Val?.toFixed(3) || 'None'}, Pixels: ${count1990Val}`);
  console.log(`2019 NDVI: ${ndvi2019Val?.toFixed(3) || 'None'}, Pixels: ${count2019Val}`);

  // Check for no valid pixels
  if (count1990Val === 0 || count2019Val === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (ndvi1990Val === null || ndvi2019Val === null || 
      isNaN(ndvi1990Val) || isNaN(ndvi2019Val) ||
      ndvi1990Val > 1 || ndvi2019Val > 1 || 
      ndvi1990Val < -1 || ndvi2019Val < -1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values
  if (ndvi2019Val < ndvi1990Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
